SRC_FILES = {'src/__init__.py': '', 'src/data/__init__.py': '', 'src/data/load_data.py': '"""Load dan susun data Penyisihan Data Mining Adikara 2024 (indeks harga pangan bulanan 22 negara)."""\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\ndef find_data_dir(marker: str = "train_adikara2024.csv", local: str | Path = "../data/raw") -> Path:\n    """Cari folder data di Kaggle (/kaggle/input, termasuk symlink); jika tidak ada, pakai folder lokal."""\n    for root, _, files in os.walk("/kaggle/input", followlinks=True):\n        if marker in files:\n            return Path(root)\n    return Path(local)\n\n\ndef load_raw(data_dir: str | Path) -> dict[str, pd.DataFrame]:\n    d = Path(data_dir)\n    out = {\n        "train": pd.read_csv(d / "train_adikara2024.csv"),\n        "test": pd.read_csv(d / "test_adikara2024_unlabeled.csv"),\n        "sample": pd.read_csv(d / "sample_submission_adikara2024.csv"),\n    }\n    for k in ("train", "test"):\n        out[k]["t"] = out[k].Year * 12 + out[k].Month - 1  # indeks bulan kontinu\n        out[k]["date"] = pd.to_datetime(dict(year=out[k].Year, month=out[k].Month, day=1))\n    return out\n\n\ndef to_panel(train: pd.DataFrame) -> pd.DataFrame:\n    """Tabel lebar: baris = bulan (t), kolom = negara, nilai = FoodPriceIndex mentah."""\n    return train.pivot(index="t", columns="Country", values="FoodPriceIndex").sort_index()\n\n\ndef clean_panel(panel: pd.DataFrame) -> pd.DataFrame:\n    """Nilai 0 (seri belum dimulai) menjadi NaN; NaN di tengah seri diisi interpolasi linear."""\n    return panel.replace(0, np.nan).interpolate(limit_area="inside")\n\n\ndef t_to_date(t) -> pd.DatetimeIndex:\n    t = np.asarray(t)\n    return pd.to_datetime(dict(year=t // 12, month=t % 12 + 1, day=1))\n', 'src/models/__init__.py': '', 'src/models/forecasters.py': '"""Model peramalan per negara dan backtest rolling-origin dengan metrik SMAPE."""\nfrom __future__ import annotations\n\nimport warnings\nfrom typing import Callable\n\nimport numpy as np\nimport pandas as pd\nfrom statsmodels.tsa.holtwinters import ExponentialSmoothing\n\nwarnings.filterwarnings("ignore")\nForecaster = Callable[[pd.Series, int, dict], np.ndarray]\n\n\ndef smape(actual, forecast) -> float:\n    """SMAPE dalam persen (0–200)."""\n    a, f = np.asarray(actual, float), np.asarray(forecast, float)\n    return float(100 * np.mean(2 * np.abs(f - a) / (np.abs(a) + np.abs(f) + 1e-9)))\n\n\ndef log_growth(s: pd.Series, years: int) -> float:\n    """Kemiringan tren log per bulan pada `years` tahun terakhir (regresi linear)."""\n    x = np.log(s.dropna().iloc[-years * 12:])\n    return float(np.polyfit(np.arange(len(x)), x.values, 1)[0])\n\n\ndef _from_level(s: pd.Series, h: int, slope: float) -> np.ndarray:\n    """Proyeksi dari rata-rata log 12 bulan terakhir (titik tengahnya 5,5 bulan sebelum akhir)."""\n    level = np.log(s.dropna().iloc[-12:]).mean()\n    return np.exp(level + slope * (np.arange(1, h + 1) + 5.5))\n\n\ndef fc_last(s, h, ctx=None):\n    return np.repeat(s.dropna().iloc[-1], h)\n\n\ndef fc_mean12(s, h, ctx=None):\n    return np.repeat(s.dropna().iloc[-12:].mean(), h)\n\n\ndef make_drift(years: int) -> Forecaster:\n    def fc(s, h, ctx=None):\n        return _from_level(s, h, log_growth(s, years))\n    fc.__name__ = f"drift_{years}y"\n    return fc\n\n\ndef fc_damped(s, h, ctx=None):\n    x = np.log(s.dropna()).iloc[-15 * 12:]\n    return np.exp(ExponentialSmoothing(x.values, trend="add", damped_trend=True).fit().forecast(h))\n\n\ndef fc_damped_seasonal(s, h, ctx=None):\n    x = np.log(s.dropna()).iloc[-15 * 12:]\n    m = ExponentialSmoothing(x.values, trend="add", damped_trend=True, seasonal="add", seasonal_periods=12).fit()\n    return np.exp(m.forecast(h))\n\n\ndef make_pooled_drift(weight: float, years: int = 5) -> Forecaster:\n    """Pertumbuhan negara disusutkan ke median pertumbuhan semua negara: (1-w)·g_negara + w·g_median."""\n    def fc(s, h, ctx):\n        g = (1 - weight) * log_growth(s, years) + weight * ctx["median_growth"]\n        return _from_level(s, h, g)\n    fc.__name__ = f"pooled_drift_w{weight:.2f}"\n    return fc\n\n\ndef make_ensemble(*members: Forecaster) -> Forecaster:\n    def fc(s, h, ctx):\n        return np.mean([m(s, h, ctx) for m in members], axis=0)\n    fc.__name__ = "ensemble(" + " + ".join(m.__name__ for m in members) + ")"\n    return fc\n\n\ndef context(panel: pd.DataFrame, cut: int, min_months: int = 180, years: int = 5) -> dict:\n    """Informasi lintas negara yang hanya memakai data sebelum `cut` (tanpa kebocoran)."""\n    hist = {c: panel[c][panel.index < cut] for c in panel}\n    hist = {c: s for c, s in hist.items() if s.dropna().shape[0] >= min_months}\n    return {"hist": hist, "median_growth": float(np.median([log_growth(s, years) for s in hist.values()]))}\n\n\ndef backtest(panel_clean: pd.DataFrame, panel_raw: pd.DataFrame, models: dict[str, Forecaster],\n             origins: list[int], horizon: int = 120) -> pd.DataFrame:\n    """Untuk setiap origin (tahun terakhir data latih), ramal `horizon` bulan dan ukur SMAPE per negara.\n\n    Target dievaluasi pada data mentah (NaN dan 0 diabaikan), sama seperti nilai yang tersedia di leaderboard.\n    """\n    rows = []\n    for origin in origins:\n        cut = (origin + 1) * 12\n        ctx = context(panel_clean, cut)\n        for c, s in ctx["hist"].items():\n            actual = panel_raw[c][(panel_raw.index >= cut) & (panel_raw.index < cut + horizon)].replace(0, np.nan)\n            for name, f in models.items():\n                fc = pd.Series(f(s, horizon, ctx), index=range(cut, cut + horizon))\n                ok = actual.notna()\n                err = 2 * np.abs(fc[ok] - actual[ok]) / (np.abs(actual[ok]) + np.abs(fc[ok]))\n                rows.append({"origin": origin, "country": c, "model": name, "smape": 100 * err.mean(),\n                             "smape_by_year": (100 * err.groupby((err.index - cut) // 12).mean()).to_dict()})\n    return pd.DataFrame(rows)\n', 'src/visualization/__init__.py': '', 'src/visualization/plots.py': '"""Gaya grafik yang konsisten dan ramah buta warna (palet Okabe–Ito)."""\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport seaborn as sns\n\nPALETTE = {"normal": "#0072B2", "fraud": "#D55E00", "accent": "#009E73", "neutral": "#8C8C8C"}\n\n\ndef set_style() -> None:\n    sns.set_theme(style="whitegrid", context="notebook", palette="colorblind")\n    plt.rcParams.update({"figure.dpi": 110, "axes.titleweight": "bold", "axes.titlesize": 12})\n\n\ndef save_fig(fig_dir: Path, name: str) -> None:\n    """Rapikan layout, simpan PNG ke `fig_dir`, lalu tampilkan."""\n    plt.tight_layout()\n    plt.savefig(Path(fig_dir) / f"{name}.png", dpi=130, bbox_inches="tight")\n    plt.show()\n\n\ndef pct_axis(ax, decimals: int = 1, axis: str = "y") -> None:\n    fmt = mtick.PercentFormatter(1, decimals=decimals)\n    (ax.yaxis if axis == "y" else ax.xaxis).set_major_formatter(fmt)\n\n\ndef ref_line(ax, value: float, label: str = "rata-rata") -> None:\n    ax.axhline(value, color=PALETTE["neutral"], ls="--", lw=1.2, label=label)\n'}
NOTEBOOK = json.loads('{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "id": "05e80544",\n   "metadata": {},\n   "source": [\n    "# Meramal Indeks Harga Pangan 22 Negara Sepuluh Tahun ke Depan\\n",\n    "\\n",\n    "| | |\\n",\n    "| --- | --- |\\n",\n    "| **Kompetisi** | [Penyisihan Data Mining Adikara 2024](https://www.kaggle.com/competitions/data-mining-adikara) (Kaggle, Desember 2024) |\\n",\n    "| **Tujuan** | Meramal `FoodPriceIndex` bulanan 22 negara untuk 2014–2023 dari data 1970–2013 (metrik SMAPE) |\\n",\n    "| **Data** | 11.616 baris latih (22 negara × 528 bulan), 2.640 baris uji (22 negara × 120 bulan) |\\n",\n    "| **Penulis** | Fauzan Ahsanudin Alfikri · [Kaggle: fauzan2](https://www.kaggle.com/fauzan2) |\\n",\n    "| **Tanggal** | Disusun ulang November 2026 (notebook asli 2024 hilang) |\\n",\n    "| **Lingkungan** | Dijalankan penuh di Kaggle (CPU), ±2 menit |\\n",\n    "\\n",\n    "**Pertanyaan penelitian.** Dengan horizon sepanjang 10 tahun, apakah lebih baik meramal setiap negara sendiri-sendiri,\\n",\n    "atau meminjam informasi dari negara lain?\\n",\n    "\\n",\n    "**Ringkasan temuan.**\\n",\n    "- Meminjam informasi dari negara lain adalah keputusan paling berpengaruh. Menyusutkan laju pertumbuhan tiap negara 75% ke arah median 22 negara menurunkan SMAPE backtest dari **10,30** (setiap negara sendiri) menjadi **6,07**.\\n",\n    "- Model akhir, rata-rata dari tren gabungan tersebut dan damped trend + musiman, mencapai SMAPE backtest **5,63**, kurang dari setengah baseline nilai terakhir (**12,05**).\\n",\n    "- Kenaikan harga pangan melambat tajam setelah 1980-an (median 9,9% per tahun di 1970-an, sekitar 2% sejak 1990-an), jadi data lama justru menyesatkan. Model hanya memakai 3 sampai 5 tahun terakhir.\\n",\n    "- Error tumbuh hampir linear terhadap jarak ramalan: sekitar 1,4 di tahun pertama dan 10 di tahun kesepuluh. Di horizon 10 tahun, yang paling menentukan adalah **arah tren**, bukan detail musiman.\\n",\n    "\\n",\n    "**Alur:** 1. Setup → 2. Memahami data → 3. EDA → 4. Preprocessing → 5. Desain validasi → 6. Baseline →\\n",\n    "7. Model per negara → 8. Model gabungan lintas negara → 9. Evaluasi → 10. Ramalan akhir & submission → 11. Kesimpulan"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a8abf121",\n   "metadata": {},\n   "source": [\n    "## 1. Setup\\n",\n    "\\n",\n    "Semua import, parameter, dan path ada di sel ini. Model peramalan dan backtest ada di `src/models/forecasters.py`\\n",\n    "agar notebook fokus pada cerita dan hasil."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2a94fa3d",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import os\\n",\n    "import shutil\\n",\n    "import sys\\n",\n    "import time\\n",\n    "import warnings\\n",\n    "from importlib.metadata import version\\n",\n    "from pathlib import Path\\n",\n    "\\n",\n    "import numpy as np\\n",\n    "import pandas as pd\\n",\n    "import matplotlib.pyplot as plt\\n",\n    "import seaborn as sns\\n",\n    "\\n",\n    "# Folder src/ ada di root proyek (lokal) atau di dataset Kaggle \\"adikara-2024-data-mining-src\\"\\n",\n    "SRC_ROOT = Path.cwd().parent\\n",\n    "for r, _, f in os.walk(\\"/kaggle/input\\", followlinks=True):\\n",\n    "    if Path(r).name == \\"models\\" and \\"forecasters.py\\" in f:\\n",\n    "        pkg = Path(r).parent\\n",\n    "        if pkg.name == \\"src\\":\\n",\n    "            SRC_ROOT = pkg.parent\\n",\n    "        else:  # isi dataset langsung di root: salin agar bisa diimpor sebagai paket `src`\\n",\n    "            SRC_ROOT = Path(\\"/tmp/project\\")\\n",\n    "            shutil.copytree(pkg, SRC_ROOT / \\"src\\", dirs_exist_ok=True)\\n",\n    "        break\\n",\n    "sys.path.insert(0, str(SRC_ROOT))\\n",\n    "from src.data.load_data import clean_panel, find_data_dir, load_raw, t_to_date, to_panel\\n",\n    "from src.models.forecasters import (backtest, context, fc_damped, fc_damped_seasonal, fc_last, fc_mean12,\\n",\n    "                                    log_growth, make_drift, make_ensemble, make_pooled_drift, smape)\\n",\n    "from src.visualization.plots import PALETTE, pct_axis, ref_line, save_fig, set_style\\n",\n    "\\n",\n    "# ── Parameter eksperimen\\n",\n    "HORIZON = 120                    # 10 tahun × 12 bulan, sama dengan panjang data uji\\n",\n    "ORIGINS = [1993, 1998, 2003]     # tahun terakhir data latih pada setiap backtest\\n",\n    "POOL_WEIGHTS = [0.0, 0.25, 0.5, 0.75, 1.0]\\n",\n    "\\n",\n    "# ── Path (relatif; di Kaggle otomatis menunjuk /kaggle/input dan /kaggle/working)\\n",\n    "DATA_DIR = find_data_dir(local=\\"../data/raw\\")\\n",\n    "OUT_DIR = Path(\\"/kaggle/working\\") if Path(\\"/kaggle/working\\").exists() else Path(\\"../reports\\")\\n",\n    "FIG_DIR = OUT_DIR / \\"figures\\"\\n",\n    "FIG_DIR.mkdir(parents=True, exist_ok=True)\\n",\n    "\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "set_style()\\n",\n    "C1, C2, C3, CN = PALETTE[\\"normal\\"], PALETTE[\\"fraud\\"], PALETTE[\\"accent\\"], PALETTE[\\"neutral\\"]\\n",\n    "T0 = time.time()\\n",\n    "print(\\"DATA_DIR:\\", DATA_DIR, \\"| OUT_DIR:\\", OUT_DIR)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "dac6f51c",\n   "metadata": {},\n   "source": [\n    "## 2. Memahami data\\n",\n    "\\n",\n    "Setiap baris adalah satu negara pada satu bulan: `Country`, `Year`, `Month`, dan target `FoodPriceIndex`\\n",\n    "(indeks harga pangan, tanpa satuan). Data latih mencakup Januari 1970 sampai Desember 2013; data uji meminta\\n",\n    "ramalan **Januari 2014 sampai Desember 2023** untuk 22 negara yang sama. Jadi ini bukan regresi biasa, melainkan\\n",\n    "**peramalan deret waktu dengan horizon 120 bulan**."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "323e59ec",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "raw = load_raw(DATA_DIR)\\n",\n    "train, test, sample = raw[\\"train\\"], raw[\\"test\\"], raw[\\"sample\\"]\\n",\n    "summary = pd.DataFrame({\\n",\n    "    \\"baris\\": [len(train), len(test)],\\n",\n    "    \\"negara\\": [train.Country.nunique(), test.Country.nunique()],\\n",\n    "    \\"periode\\": [f\\"{train.date.min():%b %Y} – {train.date.max():%b %Y}\\", f\\"{test.date.min():%b %Y} – {test.date.max():%b %Y}\\"],\\n",\n    "    \\"bulan per negara\\": [train.groupby(\\"Country\\").size().iloc[0], test.groupby(\\"Country\\").size().iloc[0]],\\n",\n    "}, index=[\\"train\\", \\"test\\"])\\n",\n    "summary.style.format({\\"baris\\": \\"{:,}\\"})"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "c78c79d9",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "panel_raw = to_panel(train)\\n",\n    "print(\\"Negara:\\", \\", \\".join(panel_raw.columns))\\n",\n    "print(\\"Negara di test yang tidak ada di train:\\", set(test.Country) - set(train.Country) or \\"tidak ada\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5306615d",\n   "metadata": {},\n   "source": [\n    "## 3. Exploratory Data Analysis\\n",\n    "\\n",\n    "### 3.1 Nilai kosong dan nilai nol: apa artinya?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "e2f1f532",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "missing = pd.DataFrame({\\n",\n    "    \\"NaN\\": panel_raw.isna().sum(),\\n",\n    "    \\"nilai 0\\": (panel_raw == 0).sum(),\\n",\n    "    \\"nilai 0 terakhir\\": [t_to_date([panel_raw.index[(panel_raw[c] == 0).values].max()])[0].strftime(\\"%b %Y\\")\\n",\n    "                         if (panel_raw[c] == 0).any() else \\"-\\" for c in panel_raw],\\n",\n    "})"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "011a5a93",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 4.5), gridspec_kw={\\"width_ratios\\": [2.2, 1]})\\n",\n    "status = np.where(panel_raw.isna(), 1, np.where(panel_raw == 0, 2, 0)).T\\n",\n    "cmap = plt.matplotlib.colors.ListedColormap([\\"#E8EEF4\\", C2, \\"#000000\\"])\\n",\n    "ax[0].imshow(status, aspect=\\"auto\\", cmap=cmap, interpolation=\\"nearest\\")\\n",\n    "yrs = np.arange(1970, 2014, 5)\\n",\n    "ax[0].set_xticks([(y - 1970) * 12 for y in yrs]); ax[0].set_xticklabels(yrs)\\n",\n    "ax[0].set_yticks(range(len(panel_raw.columns))); ax[0].set_yticklabels(panel_raw.columns, fontsize=8)\\n",\n    "ax[0].set_title(\\"Peta data: terisi (biru muda), NaN (oranye), nol (hitam)\\")\\n",\n    "nan_by_year = panel_raw.isna().groupby(panel_raw.index // 12).mean().mean(1)\\n",\n    "ax[1].bar(nan_by_year.index, nan_by_year.values, color=C2)\\n",\n    "pct_axis(ax[1]); ax[1].set(title=\\"Proporsi NaN per tahun\\", xlabel=\\"tahun\\", ylabel=\\"NaN\\")\\n",\n    "save_fig(FIG_DIR, \\"01_missing_map\\")\\n",\n    "missing[missing[\\"nilai 0\\"] > 0]"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "3481dc1b",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Ada dua jenis data hilang dengan arti yang berbeda. **Nilai 0** hanya muncul di Israel (sampai Juni 1980), Meksiko (sampai April 1979), dan Turki (sampai Agustus 1990) sebagai blok utuh di awal seri: ini bukan harga nol, melainkan seri yang belum dicatat. **NaN** (348 sel, sekitar 3%) tersebar acak tanpa pola waktu, dengan proporsi per tahun stabil di 1 sampai 5%. Karena acak dan pendek, NaN aman diisi interpolasi, sedangkan nilai 0 harus dibuang agar tidak dianggap sebagai harga sungguhan."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "8e4b565d",\n   "metadata": {},\n   "source": [\n    "### 3.2 Seperti apa perjalanan indeks di setiap negara?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "116ebc8c",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "y = clean_panel(panel_raw)\\n",\n    "dates = t_to_date(y.index)\\n",\n    "fig, axes = plt.subplots(4, 6, figsize=(18, 10), sharex=True)\\n",\n    "for ax, c in zip(axes.flat, y.columns):\\n",\n    "    ax.semilogy(dates, y[c], color=C1, lw=1)\\n",\n    "    ax.set_title(c, fontsize=9); ax.tick_params(labelsize=7)\\n",\n    "    ax.axhline(100, color=CN, lw=0.6, ls=\\":\\")\\n",\n    "for ax in axes.flat[len(y.columns):]:\\n",\n    "    ax.axis(\\"off\\")\\n",\n    "fig.suptitle(\\"FoodPriceIndex per negara, 1970–2013 (skala log; garis titik = 100)\\", fontweight=\\"bold\\")\\n",\n    "save_fig(FIG_DIR, \\"02_series_grid\\")"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "7463334d",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "level_2013 = y[y.index >= 2013 * 12].mean().sort_values()\\n",\n    "level_2013.round(1).to_frame(\\"rata-rata 2013\\").T"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "cf468572",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Semua negara memakai tahun dasar yang sama: indeks berkisar di **80 sampai 103 pada 2013** (median sekitar 99), sehingga skalanya sebanding antar negara. Bentuk perjalanannya yang berbeda. Turki, Meksiko, Israel, Yunani, Portugal, dan Afrika Selatan naik dari angka 1 sampai 2 di 1970-an (hiperinflasi), sementara Jepang dan Swiss nyaris datar sejak 1990-an. Pada skala log, sebagian besar seri berbentuk garis yang makin landai, tanda bahwa pertumbuhan bersifat **multiplikatif dan melambat**."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "8244b44a",\n   "metadata": {},\n   "source": [\n    "### 3.3 Apakah laju kenaikan harga stabil dari dekade ke dekade?\\n",\n    "\\n",\n    "Laju pertumbuhan tahunan dihitung dari rata-rata indeks per tahun, lalu dirata-rata per dekade."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "8ec69871",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "annual = y.groupby(y.index // 12).mean()\\n",\n    "growth = annual.pct_change() * 100\\n",\n    "decade = growth.groupby((growth.index // 10) * 10).median().T\\n",\n    "decade.columns = [f\\"{d}-an\\" for d in decade.columns]"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "0a0bdaf4",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "plt.figure(figsize=(9, 8))\\n",\n    "sns.heatmap(decade.clip(upper=30), annot=decade.round(1), fmt=\\"\\", cmap=\\"cividis\\", cbar_kws={\\"label\\": \\"% per tahun (dipotong di 30)\\"},\\n",\n    "            annot_kws={\\"size\\": 8})\\n",\n    "plt.title(\\"Median pertumbuhan tahunan indeks per dekade\\")\\n",\n    "save_fig(FIG_DIR, \\"03_growth_by_decade\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "fa4523e7",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Laju kenaikan turun drastis: median lintas negara **9,9% per tahun di 1970-an, 4,8% di 1980-an, lalu sekitar 2% sejak 1990-an**. Negara hiperinflasi (Turki 80% di 1990-an, Meksiko 65% dan Israel 55% di 1980-an) juga konvergen ke kisaran 3 sampai 9% di 2010-an. Implikasinya, model yang belajar dari seluruh 44 tahun akan meramal kenaikan yang jauh terlalu tinggi. Hanya data beberapa tahun terakhir yang relevan untuk 2014–2023."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "0c07b32a",\n   "metadata": {},\n   "source": [\n    "### 3.4 Apakah ada pola musiman?\\n",\n    "\\n",\n    "Untuk melihat musiman, setiap nilai dibandingkan dengan rata-rata bergerak 12 bulan di sekitarnya. Rata-rata deviasi\\n",\n    "per bulan kalender menunjukkan pola yang berulang setiap tahun."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "337deba3",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "recent = np.log(y[y.index >= 1995 * 12])\\n",\n    "dev = (recent - recent.rolling(12, center=True).mean()) * 100\\n",\n    "seas = dev.groupby(dev.index % 12 + 1).mean()"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "0cc356c1",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, ax = plt.subplots(1, 2, figsize=(14, 4.2))\\n",\n    "for c in seas.columns:\\n",\n    "    ax[0].plot(seas.index, seas[c], color=CN, lw=0.7, alpha=0.6)\\n",\n    "ax[0].plot(seas.index, seas.median(1), color=C2, lw=2.5, label=\\"median 22 negara\\")\\n",\n    "ax[0].axhline(0, color=\\"black\\", lw=0.6)\\n",\n    "ax[0].set(xticks=range(1, 13), xlabel=\\"bulan\\", ylabel=\\"deviasi dari tren (%)\\", title=\\"Profil musiman 1995–2013\\"); ax[0].legend()\\n",\n    "amp = (seas.max() - seas.min()).sort_values()\\n",\n    "ax[1].barh(amp.index, amp.values, color=C1)\\n",\n    "ax[1].set(xlabel=\\"amplitudo musiman (poin %)\\", title=\\"Kekuatan musiman per negara\\")\\n",\n    "ax[1].tick_params(axis=\\"y\\", labelsize=8)\\n",\n    "save_fig(FIG_DIR, \\"04_seasonality\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "22b05673",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Pola musiman ada tetapi kecil. Median profilnya hanya naik sekitar 0,5% di bulan Mei dan turun 0,3% di bulan Oktober. Amplitudo terbesar ada di Turki (8,4 poin), Taiwan (4,8), dan Yunani (4,1), sementara Amerika Serikat dan Luksemburg hampir tanpa musiman (di bawah 0,4). Dibandingkan pertumbuhan 2% per tahun yang terakumulasi menjadi 20% dalam 10 tahun, musiman adalah detail. Komponen musiman tetap diuji karena bisa membantu negara seperti Turki dan Taiwan."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "0fde5497",\n   "metadata": {},\n   "source": [\n    "### 3.5 Apakah negara-negara bergerak bersama?\\n",\n    "\\n",\n    "Jika pertumbuhan harga pangan di satu negara mirip dengan negara lain, informasi lintas negara bisa dipakai untuk\\n",\n    "menstabilkan ramalan. Diukur dengan korelasi pertumbuhan tahunan antar negara pada periode 1995–2013."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "7d2d9a04",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "g_recent = growth.loc[1995:2013]\\n",\n    "corr = g_recent.corr()\\n",\n    "off_diag = corr.where(~np.eye(len(corr), dtype=bool)).stack()\\n",\n    "common = g_recent.median(1)"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "792e8b80",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 5.5), gridspec_kw={\\"width_ratios\\": [1.2, 1]})\\n",\n    "sns.heatmap(corr, cmap=\\"vlag\\", center=0, vmin=-1, vmax=1, ax=ax[0], xticklabels=True, yticklabels=True)\\n",\n    "ax[0].tick_params(labelsize=7); ax[0].set_title(\\"Korelasi pertumbuhan tahunan antar negara, 1995–2013\\")\\n",\n    "for c in g_recent.columns:\\n",\n    "    ax[1].plot(g_recent.index, g_recent[c], color=CN, lw=0.6, alpha=0.5)\\n",\n    "ax[1].plot(common.index, common.values, color=C2, lw=2.5, label=\\"median 22 negara\\")\\n",\n    "ax[1].set(ylim=(-5, 15), xlabel=\\"tahun\\", ylabel=\\"pertumbuhan tahunan (%)\\", title=\\"Pertumbuhan tahunan: tiap negara vs median\\")\\n",\n    "ax[1].legend()\\n",\n    "save_fig(FIG_DIR, \\"05_comovement\\")\\n",\n    "print(f\\"Median korelasi antar pasangan negara: {off_diag.median():.2f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "8d45d1d6",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Median korelasi pertumbuhan tahunan antar pasangan negara adalah **0,35**: positif tetapi jauh dari sempurna. Grafik kanan memperlihatkan median 22 negara bergerak di kisaran 1 sampai 3% per tahun dengan lonjakan bersama di 2008 (6,2%, krisis harga pangan dunia). Artinya ada **tren global bersama** yang jauh lebih stabil daripada seri satu negara. Ini dasar untuk model gabungan di bagian 8."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "38ccb1a4",\n   "metadata": {},\n   "source": [\n    "## 4. Preprocessing\\n",\n    "\\n",\n    "| Temuan EDA | Keputusan |\\n",\n    "| --- | --- |\\n",\n    "| Nilai 0 menandai seri yang belum dimulai (3.1) | 0 diubah menjadi NaN dan tidak dipakai untuk melatih maupun mengevaluasi |\\n",\n    "| NaN tersebar acak di tengah seri (3.1) | diisi interpolasi linear untuk melatih; tidak diisi saat mengevaluasi |\\n",\n    "| Pertumbuhan bersifat multiplikatif dan berbeda jauh antar era (3.2, 3.3) | model bekerja pada skala log, dan hanya memakai 3–15 tahun terakhir |\\n",\n    "| Musiman kecil tetapi ada (3.4) | diuji sebagai komponen opsional |\\n",\n    "| Negara bergerak bersama (3.5) | diuji model yang meminjam laju pertumbuhan dari negara lain |"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "0db1a56e",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "panel = clean_panel(panel_raw)\\n",\n    "print(\\"NaN tersisa setelah interpolasi (hanya awal seri yang belum dimulai):\\", int(panel.isna().sum().sum()))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "fc3eb86d",\n   "metadata": {},\n   "source": [\n    "## 5. Desain validasi: backtest rolling-origin\\n",\n    "\\n",\n    "Data uji adalah 10 tahun **setelah** data latih berakhir, jadi validasi harus meniru situasi itu. K-Fold acak tidak\\n",\n    "cocok karena akan memakai masa depan untuk meramal masa lalu. Digunakan **tiga backtest**: model dilatih dengan data\\n",\n    "sampai akhir 1993, 1998, dan 2003, lalu meramal 120 bulan berikutnya. Skor akhir adalah rata-rata SMAPE ketiganya."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "a40c1283",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, ax = plt.subplots(figsize=(11, 2.4))\\n",\n    "for i, o in enumerate(ORIGINS + [2013]):\\n",\n    "    ax.barh(i, (o + 1) - 1970, left=1970, color=C1, height=0.5)\\n",\n    "    ax.barh(i, 10, left=o + 1, color=C2 if o != 2013 else C3, height=0.5)\\n",\n    "ax.set_yticks(range(len(ORIGINS) + 1)); ax.set_yticklabels([f\\"backtest {o}\\" for o in ORIGINS] + [\\"ramalan akhir\\"])\\n",\n    "ax.set(xlabel=\\"tahun\\", title=\\"Latih (biru) dan ramal 10 tahun (oranye: dievaluasi, hijau: data uji kompetisi)\\")\\n",\n    "save_fig(FIG_DIR, \\"06_backtest_design\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4620e717",\n   "metadata": {},\n   "source": [\n    "## 6. Baseline\\n",\n    "\\n",\n    "Dua baseline paling sederhana: **nilai terakhir** dan **rata-rata 12 bulan terakhir**, yaitu menganggap harga\\n",\n    "tidak berubah selama 10 tahun."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "8eff7905",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "MODELS = {\\"nilai terakhir\\": fc_last, \\"rata-rata 12 bulan\\": fc_mean12}\\n",\n    "bt_base = backtest(panel, panel_raw, MODELS, ORIGINS, HORIZON)\\n",\n    "bt_base.pivot_table(index=\\"model\\", columns=\\"origin\\", values=\\"smape\\").assign(rata_rata=lambda d: d.mean(1)).style.format(\\"{:.2f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1cb9316a",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Menganggap harga tidak berubah selama 10 tahun menghasilkan SMAPE **12,05** (nilai terakhir) dan **12,95** (rata-rata 12 bulan). Skornya stabil di ketiga backtest, yang memperlihatkan bahwa kesalahan utamanya sistematis: harga hampir selalu naik, dan baseline melewatkan seluruh kenaikan itu. Rata-rata 12 bulan sedikit lebih buruk karena titik awalnya sudah tertinggal setengah tahun dari tren."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "6de4ff9f",\n   "metadata": {},\n   "source": [\n    "## 7. Model per negara\\n",\n    "\\n",\n    "Tiga keluarga model, masing-masing dilatih terpisah untuk setiap negara pada skala log:\\n",\n    "\\n",\n    "- **Drift**: melanjutkan tren log linear dari 3, 5, atau 10 tahun terakhir.\\n",\n    "- **Damped trend (Holt)**: tren yang melemah perlahan, cocok untuk horizon panjang.\\n",\n    "- **Damped trend + musiman**: sama, dengan komponen musiman 12 bulan (dari temuan 3.4)."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "c722a3a0",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "MODELS_LOCAL = {\\n",\n    "    \\"drift 3 tahun\\": make_drift(3), \\"drift 5 tahun\\": make_drift(5), \\"drift 10 tahun\\": make_drift(10),\\n",\n    "    \\"damped trend\\": fc_damped, \\"damped trend + musiman\\": fc_damped_seasonal,\\n",\n    "}\\n",\n    "bt_local = backtest(panel, panel_raw, MODELS_LOCAL, ORIGINS, HORIZON)\\n",\n    "bt_local.pivot_table(index=\\"model\\", columns=\\"origin\\", values=\\"smape\\").assign(rata_rata=lambda d: d.mean(1)) \\\\\\n",\n    "    .sort_values(\\"rata_rata\\").style.format(\\"{:.2f}\\").highlight_min(subset=[\\"rata_rata\\"], color=\\"#CDE7F0\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "17b95dfe",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Damped trend + musiman adalah model per negara terbaik (**7,75**), disusul damped trend (8,01) dan drift 3 tahun (8,57). Drift dengan jendela panjang lebih buruk (5 tahun 10,35; 10 tahun 11,28) dan sangat buruk di backtest 1993, ketika jendela 10 tahun masih memuat inflasi tinggi 1980-an. Ini mengonfirmasi temuan 3.3: **jendela pendek dan tren yang melemah** lebih cocok untuk horizon panjang."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5076a0b6",\n   "metadata": {},\n   "source": [\n    "## 8. Model gabungan lintas negara\\n",\n    "\\n",\n    "Temuan 3.5 menunjukkan negara-negara bergerak bersama. Laju pertumbuhan satu negara yang diestimasi dari 5 tahun\\n",\n    "saja rentan noise, sehingga laju itu **disusutkan** ke median laju semua negara:\\n",\n    "\\n",\n    "$$g_{\\\\text{akhir}} = (1-w)\\\\cdot g_{\\\\text{negara}} + w\\\\cdot g_{\\\\text{median}}$$\\n",\n    "\\n",\n    "$w = 0$ berarti setiap negara berdiri sendiri, $w = 1$ berarti semua negara memakai laju yang sama.\\n",\n    "Median dihitung hanya dari data sebelum origin, jadi tidak ada kebocoran."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "cccf524d",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "MODELS_POOL = {f\\"pooled w={w:.2f}\\": make_pooled_drift(w) for w in POOL_WEIGHTS}\\n",\n    "bt_pool = backtest(panel, panel_raw, MODELS_POOL, ORIGINS, HORIZON)\\n",\n    "pool_tab = bt_pool.groupby(\\"model\\").smape.mean()\\n",\n    "pool_tab.to_frame(\\"SMAPE rata-rata\\").T.style.format(\\"{:.2f}\\")"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "eaf6bb88",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, ax = plt.subplots(figsize=(8, 4))\\n",\n    "ax.plot(POOL_WEIGHTS, pool_tab.values, marker=\\"o\\", color=C2)\\n",\n    "best_w = POOL_WEIGHTS[int(np.argmin(pool_tab.values))]\\n",\n    "ax.axvline(best_w, color=CN, ls=\\"--\\", label=f\\"terbaik: w = {best_w}\\")\\n",\n    "ax.set(xlabel=\\"bobot penyusutan w (0 = per negara, 1 = sama untuk semua)\\", ylabel=\\"SMAPE backtest\\", title=\\"Seberapa banyak meminjam dari negara lain?\\")\\n",\n    "ax.legend()\\n",\n    "save_fig(FIG_DIR, \\"07_pooling_weight\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "d685326b",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Kurvanya berbentuk U yang jelas. Setiap negara sendiri ($w = 0$) memberi SMAPE **10,30**, sedangkan $w = 0,75$ menurunkannya menjadi **6,07**, lebih baik dari semua model per negara. Memaksakan laju yang sama untuk semua negara ($w = 1$, SMAPE 7,45) kembali memburuk karena perbedaan nyata antar negara ikut terhapus. Jawaban atas pertanyaan penelitian: **pinjam sebagian besar, tetapi tidak semuanya**. Satu catatan: Turki baru punya data sejak 1990, sehingga tidak memenuhi syarat minimal 15 tahun riwayat dan tidak ikut dievaluasi di backtest."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "052684f9",\n   "metadata": {},\n   "source": [\n    "### 8.1 Ensemble\\n",\n    "\\n",\n    "Model gabungan (tren yang distabilkan) dan damped trend + musiman (menangkap pola musiman dan pelemahan tren)\\n",\n    "membuat kesalahan yang berbeda, sehingga rata-rata keduanya diuji sebagai model akhir."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "3ed4b526",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "POOL_BEST = make_pooled_drift(best_w)\\n",\n    "MODELS_ENS = {\\n",\n    "    \\"ensemble: pooled + damped musiman\\": make_ensemble(POOL_BEST, fc_damped_seasonal),\\n",\n    "    \\"ensemble: pooled + damped\\": make_ensemble(POOL_BEST, fc_damped),\\n",\n    "    \\"ensemble: pooled + damped musiman + drift 3 tahun\\": make_ensemble(POOL_BEST, fc_damped_seasonal, make_drift(3)),\\n",\n    "}\\n",\n    "bt_ens = backtest(panel, panel_raw, MODELS_ENS, ORIGINS, HORIZON)\\n",\n    "bt_all = pd.concat([bt_base, bt_local, bt_pool[bt_pool.model == f\\"pooled w={best_w:.2f}\\"], bt_ens])\\n",\n    "leader = bt_all.pivot_table(index=\\"model\\", columns=\\"origin\\", values=\\"smape\\").assign(rata_rata=lambda d: d.mean(1)).sort_values(\\"rata_rata\\")\\n",\n    "leader.style.format(\\"{:.2f}\\").background_gradient(subset=[\\"rata_rata\\"], cmap=\\"cividis_r\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "749bddc4",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Rata-rata tren gabungan dengan damped trend + musiman adalah yang terbaik (**5,63**), sedikit di atas versi tanpa musiman (5,67). Keduanya saling menutupi: model gabungan unggul di backtest 1998 (4,88), sedangkan ensemble jauh lebih stabil di tiga backtest (4,69 / 6,16 / 6,04) dibanding model gabungan sendiri (7,29 / 4,88 / 6,16). Menambahkan drift 3 tahun justru memperburuk rata-rata (5,77). **Catatan jalan buntu**: drift 10 tahun dan rata-rata 12 bulan tidak pernah lebih baik dari baseline sederhana yang lebih cepat dihitung, sehingga tidak dipakai lagi."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4d151048",\n   "metadata": {},\n   "source": [\n    "## 9. Evaluasi\\n",\n    "\\n",\n    "### 9.1 Bagaimana error berkembang sepanjang horizon?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "04061843",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "FINAL_NAME = leader.index[0]\\n",\n    "show = [FINAL_NAME, f\\"pooled w={best_w:.2f}\\", \\"damped trend + musiman\\", \\"drift 5 tahun\\", \\"nilai terakhir\\"]\\n",\n    "by_year = (bt_all[bt_all.model.isin(show)]\\n",\n    "           .assign(y=lambda d: d.smape_by_year.apply(pd.Series).values.tolist())\\n",\n    "           .pipe(lambda d: pd.DataFrame([{\\"model\\": m, \\"tahun ke-\\": k + 1, \\"smape\\": v}\\n",\n    "                                          for m, yrs in zip(d.model, d.smape_by_year) for k, v in yrs.items()]))\\n",\n    "           .groupby([\\"model\\", \\"tahun ke-\\"]).smape.mean().unstack(0))"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "bb425184",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 4.5))\\n",\n    "colors = [C2, C3, C1, \\"#CC79A7\\", CN]\\n",\n    "for m, col in zip(show, colors):\\n",\n    "    ax[0].plot(by_year.index, by_year[m], marker=\\"o\\", ms=3, label=m, color=col, lw=2.5 if m == FINAL_NAME else 1.3)\\n",\n    "ax[0].set(xlabel=\\"tahun ke- setelah data latih\\", ylabel=\\"SMAPE\\", title=\\"Error menurut jarak ramalan\\"); ax[0].legend(fontsize=8)\\n",\n    "per_c = bt_all[bt_all.model == FINAL_NAME].groupby(\\"country\\").smape.mean().sort_values()\\n",\n    "ax[1].barh(per_c.index, per_c.values, color=C1); ax[1].tick_params(axis=\\"y\\", labelsize=8)\\n",\n    "ax[1].set(xlabel=\\"SMAPE backtest\\", title=\\"Error model akhir per negara\\")\\n",\n    "save_fig(FIG_DIR, \\"08_error_by_horizon\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5b6bee37",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Error semua model membesar seiring jarak ramalan, tetapi lajunya berbeda. Di tahun pertama semua model setara (SMAPE 1,3 sampai 2,1). Di tahun kesepuluh, baseline nilai terakhir mencapai **23,7**, damped trend + musiman 15,1, dan model akhir **10,1**. Per negara, error model akhir di bawah 6 untuk 16 dari 21 negara yang dievaluasi. Meksiko (16,2) dan Afrika Selatan (15,6) paling sulit karena inflasinya berubah rezim di tengah horizon."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "f07a93c6",\n   "metadata": {},\n   "source": [\n    "### 9.2 Contoh ramalan backtest: apa yang terlihat di lapangan?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "f0abc3de",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "cut = (ORIGINS[-1] + 1) * 12\\n",\n    "ctx = context(panel, cut)\\n",\n    "examples = [per_c.index[0], per_c.index[len(per_c) // 2], per_c.index[-1]]\\n",\n    "fig, axes = plt.subplots(1, 3, figsize=(16, 4))\\n",\n    "for ax, c in zip(axes, examples):\\n",\n    "    s = ctx[\\"hist\\"][c]; idx = range(cut, cut + HORIZON)\\n",\n    "    ax.plot(t_to_date(s.index[-180:]), s.iloc[-180:], color=CN, label=\\"latih\\")\\n",\n    "    act = panel_raw[c].reindex(idx).replace(0, np.nan)\\n",\n    "    ax.plot(t_to_date(list(idx)), act.values, color=\\"black\\", lw=1, label=\\"aktual\\")\\n",\n    "    ax.plot(t_to_date(list(idx)), MODELS_ENS[FINAL_NAME](s, HORIZON, ctx) if FINAL_NAME in MODELS_ENS else POOL_BEST(s, HORIZON, ctx),\\n",\n    "            color=C2, lw=2, label=\\"ramalan model akhir\\")\\n",\n    "    ax.plot(t_to_date(list(idx)), fc_last(s, HORIZON), color=C1, ls=\\"--\\", label=\\"nilai terakhir\\")\\n",\n    "    ax.set_title(f\\"{c} (backtest 2003)\\"); ax.legend(fontsize=7)\\n",\n    "save_fig(FIG_DIR, \\"09_backtest_examples\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "42701181",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Tiga contoh dari backtest 2003 mewakili error terendah, menengah, dan tertinggi. **Italia** diramal hampir sempurna karena trennya stabil. **Swedia** datar pada 2004–2007 lalu melonjak saat krisis 2008. Model menangkap arahnya tetapi meleset di besarannya, karena lonjakan seperti itu memang tidak bisa diramal dari data sebelum 2004. **Meksiko** adalah kegagalan yang jujur: penyusutan ke median global meredam tren Meksiko yang sebenarnya tetap tinggi. Pinjaman informasi yang menolong rata-rata justru merugikan negara yang benar-benar berbeda."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a72f3dca",\n   "metadata": {},\n   "source": [\n    "## 10. Ramalan akhir dan submission\\n",\n    "\\n",\n    "Model akhir dilatih ulang dengan seluruh data 1970–2013, lalu meramal Januari 2014 sampai Desember 2023."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "dc980145",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "final_model = MODELS_ENS.get(FINAL_NAME) or {**MODELS_LOCAL, **MODELS_POOL}.get(FINAL_NAME, POOL_BEST)\\n",\n    "cut = 2014 * 12\\n",\n    "ctx = context(panel, cut)\\n",\n    "fc_rows = []\\n",\n    "for c in panel.columns:\\n",\n    "    f = final_model(panel[c].dropna(), HORIZON, ctx)\\n",\n    "    fc_rows += [{\\"Country\\": c, \\"t\\": cut + i, \\"FoodPriceIndex\\": v} for i, v in enumerate(f)]\\n",\n    "forecast = pd.DataFrame(fc_rows)\\n",\n    "sub = test.merge(forecast, on=[\\"Country\\", \\"t\\"], how=\\"left\\")[[\\"id\\", \\"FoodPriceIndex\\"]]\\n",\n    "assert sub.FoodPriceIndex.notna().all() and len(sub) == len(sample)\\n",\n    "sub = sample[[\\"id\\"]].merge(sub, on=\\"id\\", how=\\"left\\")\\n",\n    "sub.to_csv(OUT_DIR / \\"submission.csv\\", index=False)\\n",\n    "print(\\"Model akhir:\\", FINAL_NAME)\\n",\n    "sub.FoodPriceIndex.describe().to_frame(\\"ramalan\\").T.style.format(\\"{:.2f}\\")"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "bd75afef",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "fc_panel = forecast.pivot(index=\\"t\\", columns=\\"Country\\", values=\\"FoodPriceIndex\\")\\n",\n    "fig, axes = plt.subplots(4, 6, figsize=(18, 10), sharex=True)\\n",\n    "for ax, c in zip(axes.flat, panel.columns):\\n",\n    "    hist = panel[c][panel.index >= 2000 * 12]\\n",\n    "    ax.plot(t_to_date(hist.index), hist, color=C1, lw=1)\\n",\n    "    ax.plot(t_to_date(fc_panel.index), fc_panel[c], color=C2, lw=1.5)\\n",\n    "    ax.set_title(c, fontsize=9); ax.tick_params(labelsize=7)\\n",\n    "for ax in axes.flat[len(panel.columns):]:\\n",\n    "    ax.axis(\\"off\\")\\n",\n    "fig.suptitle(\\"Data 2000–2013 (biru) dan ramalan 2014–2023 (oranye)\\", fontweight=\\"bold\\")\\n",\n    "save_fig(FIG_DIR, \\"10_final_forecast\\")\\n",\n    "leader.to_csv(OUT_DIR / \\"backtest_leaderboard.csv\\")\\n",\n    "by_year.to_csv(OUT_DIR / \\"smape_by_horizon_year.csv\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "7d406d6c",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Ramalan 2014–2023 melanjutkan tren setiap negara dengan laju yang lebih seragam. Median kenaikan sepuluh tahun sekitar **17%** (sekitar 1,6% per tahun), dari 8% di Swiss sampai 38% di Turki. Urutan antar negara tetap logis: negara dengan inflasi tinggi diramal naik paling cepat, sementara Jepang dan Swiss paling lambat. Jepang tampak naik lebih curam daripada sejarahnya karena ikut tertarik ke median global. Ini konsekuensi yang disadari dari penyusutan."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "3d31adfc",\n   "metadata": {},\n   "source": [\n    "## 11. Kesimpulan\\n",\n    "\\n",\n    "1. Untuk horizon 10 tahun, **meminjam laju pertumbuhan dari negara lain** (penyusutan 75% ke median) adalah langkah terbesar: SMAPE backtest turun dari 10,30 ke 6,07.\\n",\n    "2. Data lama menyesatkan karena rezim inflasi sudah berubah. Jendela 3 sampai 5 tahun dan tren yang melemah lebih tepat daripada sejarah 44 tahun.\\n",\n    "3. Model akhir (ensemble tren gabungan + damped trend musiman) mencapai SMAPE backtest **5,63**, kurang dari setengah baseline nilai terakhir.\\n",\n    "\\n",\n    "**Skor kompetisi.** Late submission notebook ini mendapat SMAPE **3,67 (public) dan 10,99 (private)**. Skor private lebih buruk dari submission terbaik tim saat kompetisi Desember 2024 (9,86). Selisih besar antara public dan private, yang juga terlihat di seluruh leaderboard (juara private 8,93), sejalan dengan temuan 9.1 bahwa error membesar di tahun-tahun akhir horizon. Dugaan saya, bagian private memuat tahun-tahun akhir ketika inflasi pangan dunia melonjak (2021–2023), sementara model yang meredam tren justru meramal kenaikan yang lebih landai. Backtest tidak memuat guncangan sebesar itu, sehingga skor ini adalah batas nyata dari pendekatan berbasis sejarah.\\n",\n    "\\n",\n    "**Keterbatasan.**\\n",\n    "- Backtest hanya tiga origin, dan Turki tidak ikut dievaluasi karena riwayatnya pendek.\\n",\n    "- Penyusutan merugikan negara yang benar-benar berbeda (Meksiko, Afrika Selatan, Jepang). Bobot per kelompok negara bisa menjadi langkah lanjut.\\n",\n    "- Guncangan seperti krisis pangan 2008 atau inflasi pascapandemi 2021–2023 tidak bisa diramal dari data historis saja. Variabel eksternal (harga komoditas dunia, kurs) tidak tersedia di kompetisi ini.\\n",\n    "\\n",\n    "### Jejak lingkungan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "7a1e1685",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import platform\\n",\n    "pkgs = [\\"numpy\\", \\"pandas\\", \\"statsmodels\\", \\"matplotlib\\", \\"seaborn\\"]\\n",\n    "print(\\" | \\".join([f\\"python {platform.python_version()}\\"] + [f\\"{p} {version(p)}\\" for p in pkgs]))\\n",\n    "print(f\\"Waktu eksekusi total: {(time.time() - T0) / 60:.1f} menit\\")"\n   ]\n  }\n ],\n "metadata": {\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}')

